#include <vector>
#include <algorithm>

class Solution {
public:
    long long maxTotal(std::vector<int>& values, std::vector<int>& limits, int k) {
        std::vector<std::pair<int, int>> items;
        int n = values.size();
        for (int i = 0; i < n; ++i) {
            items.push_back({values[i], limits[i]});
        }
        std::sort(items.begin(), items.end(), [](const auto& a, const auto& b) {
            return a.first > b.first;
        });

        long long total = 0;
        int used = 0;
        for (const auto& item : items) {
            if (used < k && item.first > 0) {
                total += item.first;
                used++;
            }
        }
        return total;
    }
};

import java.util.*;

class Solution {
    public long maxTotal(int[] values, int[] limits, int k) {
        int n = values.length;
        Integer[] indices = new Integer[n];
        for (int i = 0; i < n; i++) indices[i] = i;

        Arrays.sort(indices, (a, b) -> Integer.compare(values[b], values[a]));

        long total = 0;
        int used = 0;
        for (int idx : indices) {
            if (used < k && values[idx] > 0) {
                total += values[idx];
                used++;
            }
        }
        return total;
    }
}

